{{
  (() => {
    const multiselectFields = ['sm', 'partners', 'protocol_types', 'protocols', 'purposes', 'restrictions'];

    const normalize = (obj) => {
      const cleaned = _.omit(obj, ['locations_stages']);
      return _.mapValues(cleaned, (val, key) => {
        if (multiselectFields.includes(key)) {
          return (val || []).map(String).sort();
        }
        if (val === null || val === undefined) return '';
        return val;
      });
    };

    const formNormalized = normalize(JSONForm1.formData);
    const viewNormalized = normalize(appsmith.store.viewData);

    const allKeys = _.union(_.keys(formNormalized), _.keys(viewNormalized));

    const diffs = allKeys
      .filter(key => !_.isEqual(formNormalized[key], viewNormalized[key]))
      .map(key => `- ${key}`);

    return diffs.length
      ? `Changed fields:\n${diffs.join('\n')}`
      : "No changes detected.";
  })()
}}
